let LANG_IDX = 0;
function T(key, vars) {
  const e = I18N[key];
  let s = e ? (e[LANG_IDX] || e[1] || e[0]) : key;
  if (vars) for (const k in vars) s = s.split('{' + k + '}').join(vars[k]);
  return s;
}
function setLangIndex(code) { const i = LANGS.findIndex(l => l[0] === code); LANG_IDX = i < 0 ? 0 : i; }

